package ir.daftarsetareh.offline;

import android.graphics.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.time.LocalDate;
import java.util.*;

/** The native presentation layer: persistent state is always read from Store. */
final class Screens {
    final MainActivity a;final Ui ui;final Store db;final Forms forms;int reportsLimit=30,examsLimit=30;
    Screens(MainActivity activity){a=activity;ui=a.ui;db=a.store;forms=a.forms;}
    void title(LinearLayout box,String title,String subtitle){ui.add(box,ui.text(title,25,Ui.INK));ui.space(box,5);ui.add(box,ui.text(subtitle,13,Ui.MUTED));ui.space(box,12);}
    void heading(LinearLayout box,String title){ui.space(box,12);ui.add(box,ui.label(title));ui.space(box,7);}
    List<JSONObject> sorted(String collection,boolean ascending){List<JSONObject> values=db.all(collection);values.sort(Comparator.comparing(item->item.optString("date")+item.optString("time")));if(!ascending)Collections.reverse(values);return values;}
    String grade(Double value){return Dates.decimal(value==null?null:value*db.profile().optDouble("scale",20)/100)+" از "+Dates.fa(db.profile().optDouble("scale",20));}
    void remove(String collection,JSONObject value){ui.confirm("حذف این مورد؟","این رکورد از دفتر همین گوشی حذف می‌شود. بقیهٔ اطلاعات حفظ می‌شود.",()->{db.remove(collection,value.optString("id"));a.refresh();});}
    void persistCheck(CheckBox checkbox,String collection,JSONObject record,JSONObject value){boolean[] reverting={false};checkbox.setOnCheckedChangeListener((button,checked)->{if(reverting[0])return;boolean previous=value.optBoolean("completed");try{value.put("completed",checked);db.save(collection,record);}catch(Exception error){try{value.put("completed",previous);}catch(JSONException ignored){}reverting[0]=true;checkbox.setChecked(previous);reverting[0]=false;ui.toast("تغییر ذخیره نشد؛ وضعیت قبلی حفظ شد. "+error.getMessage());}});}
    void home(LinearLayout box){
        String today=Dates.today();JSONObject profile=db.profile();title(box,"سلام "+profile.optString("name")+" ✨",Dates.format(today));
        LinearLayout hero=ui.card(box);GradientDrawableCompat.brand(ui,hero);ui.add(hero,ui.text("هر روز یک صفحهٔ تازه",22,Color.WHITE));ui.space(hero,7);ui.add(hero,ui.text("تلاش‌های کوچک امروز، ستاره‌های فردا هستند.",14,Color.WHITE));int minutes=db.totalMinutes(today,today),goal=profile.optInt("dailyGoal",90);ui.space(hero,16);ui.add(hero,ui.text(Dates.fa(minutes)+" / "+Dates.fa(goal)+" دقیقه",28,0xffffe6a3));ui.progress(hero,minutes,goal);ui.add(hero,ui.text(minutes>=goal?"✦ هدف امروزت کامل شده؛ آفرین به استمرار تو!":"هدف روزانهٔ خودت؛ بدون مقایسه با دیگران",12,Color.WHITE));
        String[] week=Dates.period(today,"weekly");LinearLayout stats=ui.card(box);ui.stat(stats,"مطالعهٔ این هفته",Dates.fa(db.totalMinutes(week[0],week[1]))+" دقیقه");ui.stat(stats,"میانگین همهٔ درس‌ها",grade(db.average("1921-01-01","2122-12-31")));ui.stat(stats,"کار انجام‌شدهٔ امروز",Dates.fa(db.tasks(today,today,true)));ui.stat(stats,"روزهای پیوستهٔ مطالعه",Dates.fa(streak(today))+" روز");
        ui.buttons(box,"+ گزارش امروز",()->forms.report(null),"+ آزمون",()->forms.exam(null));
        LinearLayout chart=ui.card(box);ui.add(chart,ui.label("رد پای مطالعهٔ این هفته"));StudyChart view=new StudyChart(a,week[0]);chart.addView(view,new LinearLayout.LayoutParams(-1,ui.dp(160)));ui.add(chart,ui.text("نمودار از دقیقه‌های واقعی ثبت‌شده در گزارش‌ها ساخته می‌شود.",11,Ui.MUTED));
        heading(box,"امروز در برنامهٔ تو");int count=0;for(JSONObject session:sorted("sessions",true))if(today.equals(session.optString("date"))){sessionCard(box,session);count++;}if(count==0)ui.empty(box,"امروز هنوز برنامه‌ای نداری","با یک جلسهٔ کوتاه شروع کن و بعد از انجامش تیک بزن.");
        ui.add(box,ui.button("دیدن برنامه و هدف‌ها",false,()->a.navigate("planner")));
    }
    int streak(String today){Set<String> days=new HashSet<>();for(JSONObject report:db.all("reports"))if(Store.minutes(report)>0)days.add(report.optString("date"));LocalDate cursor=LocalDate.parse(today);if(!days.contains(today))cursor=cursor.minusDays(1);int result=0;while(days.contains(cursor.toString())){result++;cursor=cursor.minusDays(1);}return result;}
    void reports(LinearLayout box){title(box,"گزارش‌های روزانه","زمان مطالعه، کارها و آنچه یاد گرفتی؛ هر روز یک قدم.");ui.add(box,ui.button("+ ثبت گزارش تازه",true,()->forms.report(null)));List<JSONObject> reports=sorted("reports",false);if(reports.isEmpty()){ui.empty(box,"اولین صفحهٔ دفترت را بنویس","ثبت یک درس یا حتی یک یادداشت کوتاه کافی است.");return;}
        for(JSONObject report:reports.subList(0,Math.min(reportsLimit,reports.size()))){LinearLayout card=ui.card(box);ui.add(card,ui.label(Dates.format(report.optString("date"))));ui.add(card,ui.text(Dates.fa(Store.minutes(report))+" دقیقه مطالعه",18,Ui.PURPLE));JSONArray rows=report.optJSONArray("subjects");for(int i=0;i<rows.length();i++){JSONObject row=rows.optJSONObject(i);ui.add(card,ui.text(db.subjectName(row.optString("subjectId"))+" • "+Dates.fa(row.optInt("minutes"))+" دقیقه",13,Ui.MUTED));}
            String[] fields={"lessons","exercises","difficulties","reflection","nextGoals"},labels={"مرور درس","تمرین‌ها","چالش امروز","یادداشت امروز","قدم بعدی"};for(int i=0;i<fields.length;i++)if(!report.optString(fields[i]).isEmpty()){ui.space(card,8);ui.add(card,ui.label(labels[i]));ui.add(card,ui.text(report.optString(fields[i]),14,Ui.INK));}
            JSONArray tasks=report.optJSONArray("tasks");for(int i=0;i<tasks.length();i++){JSONObject task=tasks.optJSONObject(i);CheckBox checkbox=new CheckBox(a);checkbox.setText(task.optString("title"));checkbox.setTypeface(ui.font);checkbox.setTextColor(Ui.INK);checkbox.setMinHeight(ui.dp(48));checkbox.setChecked(task.optBoolean("completed"));persistCheck(checkbox,"reports",report,task);ui.add(card,checkbox);}
            ui.buttons(card,"ویرایش",()->forms.report(report),"حذف",()->remove("reports",report));
        }if(reports.size()>reportsLimit)ui.add(box,ui.button("نمایش گزارش‌های بیشتر • "+Dates.fa(reports.size())+" گزارش در دفتر",false,()->{reportsLimit+=30;a.refresh();}));
    }
    void exams(LinearLayout box){title(box,"آزمون‌ها و نمره‌ها","نمرهٔ خالی یعنی اعلام‌نشده؛ صفر واقعی در میانگین حساب می‌شود.");ui.add(box,ui.button("+ آزمون تازه",true,()->forms.exam(null)));LinearLayout summary=ui.card(box);ui.stat(summary,"میانگین کل",grade(db.average("1921-01-01","2122-12-31")));ui.add(summary,ui.text("میانگین کل از میانگین برابر درس‌های نمره‌دار ساخته می‌شود. ضریب هر آزمون در میانگین همان درس اثر دارد.",12,Ui.MUTED));
        for(Map.Entry<String,Double> row:db.subjectAverages("1921-01-01","2122-12-31").entrySet())if(row.getValue()!=null)ui.stat(summary,db.subjectName(row.getKey()),grade(row.getValue()));
        List<JSONObject> exams=sorted("exams",false);if(exams.isEmpty())ui.empty(box,"هنوز آزمونی ثبت نشده","آزمون آینده را هم می‌توانی بدون نمره ذخیره کنی.");
        for(JSONObject exam:exams.subList(0,Math.min(examsLimit,exams.size()))){LinearLayout card=ui.card(box);ui.add(card,ui.text(db.subjectName(exam.optString("subjectId")),12,Ui.PURPLE));ui.add(card,ui.label(exam.optString("title")));ui.add(card,ui.text(Dates.format(exam.optString("date")),12,Ui.MUTED));ui.space(card,10);ui.add(card,ui.text(exam.isNull("grade")?"در انتظار نمره":Dates.fa(exam.optDouble("grade"))+" از "+Dates.fa(exam.optDouble("maxGrade"))+"  •  "+Dates.decimal(Core.percent(exam.optDouble("grade"),exam.optDouble("maxGrade")))+"٪",22,exam.isNull("grade")?Ui.GOLD:Ui.TEAL));ui.add(card,ui.text("ضریب: "+(exam.isNull("weight")?"۱ (پیش‌فرض)":Dates.fa(exam.optDouble("weight"))),12,Ui.MUTED));if(!exam.optString("notes").isEmpty())ui.add(card,ui.text(exam.optString("notes"),14,Ui.INK));ui.buttons(card,"ویرایش",()->forms.exam(exam),"حذف",()->remove("exams",exam));}if(exams.size()>examsLimit)ui.add(box,ui.button("نمایش آزمون‌های بیشتر • "+Dates.fa(exams.size())+" آزمون در دفتر",false,()->{examsLimit+=30;a.refresh();}));
    }
    void range(LinearLayout box,String kind){Button date=ui.button(Dates.format(a.referenceDate),false,()->{});date.setTag(a.referenceDate);date.setOnClickListener(view->ui.pickDate(date,iso->{a.referenceDate=iso;a.refresh();}));ui.add(box,date);String[] period=Dates.period(a.referenceDate,kind);ui.space(box,8);ui.add(box,ui.text(Dates.format(period[0])+" تا "+Dates.format(period[1]),12,Ui.MUTED));ui.buttons(box,"← دورهٔ بعد",()->{a.referenceDate=shift(period[0],kind,1);a.refresh();},"دورهٔ قبل →",()->{a.referenceDate=shift(period[0],kind,-1);a.refresh();});}
    String shift(String date,String kind,int direction){if(kind.equals("weekly"))return LocalDate.parse(date).plusDays(direction*7L).toString();int[] j=Dates.jalali(date);int month=j[1]+direction,year=j[0];if(month==13){month=1;year++;}if(month==0){month=12;year--;}return Dates.iso(year,month,1);}
    void planner(LinearLayout box){title(box,"برنامهٔ مطالعه","جلسه‌ها را مرتب کن؛ هر تیک، یک قدم رو به جلوست.");range(box,"weekly");ui.buttons(box,"+ برنامهٔ تازه",()->forms.session(null),"هدف‌های من",()->a.navigate("goals"));String[] period=Dates.period(a.referenceDate,"weekly");int count=0;for(JSONObject session:sorted("sessions",true))if(Core.inRange(session.optString("date"),period[0],period[1])){sessionCard(box,session);count++;}if(count==0)ui.empty(box,"این هفته هنوز برنامه‌ای ندارد","یک جلسه یا یک مجموعهٔ تکرارشونده بساز. روزهای هفته و پایان تکرار قابل انتخاب‌اند.");}
    void sessionCard(LinearLayout box,JSONObject session){LinearLayout card=ui.card(box);ui.add(card,ui.text(Dates.format(session.optString("date"))+" • "+Dates.fa(session.optString("time")),12,Ui.MUTED));CheckBox done=new CheckBox(a);done.setText(session.optString("title"));done.setTypeface(ui.font);done.setTextSize(17);done.setTextColor(Ui.INK);done.setMinHeight(ui.dp(48));done.setChecked(session.optBoolean("completed"));persistCheck(done,"sessions",session,session);ui.add(card,done);ui.add(card,ui.text(db.subjectName(session.optString("subjectId"))+" • "+session.optString("kind")+" • "+Dates.fa(session.optInt("duration"))+" دقیقه • "+session.optString("priority"),12,Ui.PURPLE));if(!session.optString("notes").isEmpty())ui.add(card,ui.text(session.optString("notes"),13,Ui.MUTED));ui.buttons(card,"ویرایش",()->forms.session(session),"حذف جلسه",()->remove("sessions",session));if(!session.optString("seriesId").isEmpty())ui.add(card,ui.button("حذف همهٔ جلسه‌های این مجموعه",false,()->ui.confirm("حذف مجموعهٔ تکرار؟","همهٔ جلسه‌های این مجموعه، از جمله جلسه‌های تکمیل‌شده، حذف می‌شوند. گزارش‌های واقعی مطالعه حفظ می‌شوند.",()->{db.removeSeries(session.optString("seriesId"));a.refresh();})));}
    void goals(LinearLayout box){title(box,"هدف‌ها و ستاره‌ها","پیشرفت واقعی، بر اساس اطلاعاتی که در دفترت ثبت کرده‌ای.");ui.add(box,ui.button("+ هدف تازه",true,()->forms.goal(null)));List<JSONObject> goals=db.all("goals");if(goals.isEmpty())ui.empty(box,"یک هدف کوچک انتخاب کن","دقیقهٔ مطالعه، کار انجام‌شده یا میانگین نمره؛ روزانه، هفتگی یا ماهانه.");for(JSONObject goal:goals){LinearLayout card=ui.card(box);double current=db.goalValue(goal,Dates.today()),target=goal.optDouble("target");int percent=(int)Math.min(100,Math.round(current*100/target));ui.add(card,ui.label((current>=target&&goal.optBoolean("active")?"✦ ":"")+goal.optString("title")));String period=goal.optString("period").equals("daily")?"روزانه":goal.optString("period").equals("weekly")?"هفتگی":"ماهانه";String unit=goal.optString("metric").equals("minutes")?"دقیقه":goal.optString("metric").equals("tasks")?"کار":"درصد";ui.add(card,ui.text(period+" • "+(goal.optBoolean("active")?"فعال":"متوقف"),12,Ui.MUTED));ui.progress(card,current,target);ui.stat(card,Dates.decimal(current)+" / "+Dates.decimal(target)+" "+unit,Dates.fa(percent)+"٪");String milestones="";for(int step:new int[]{25,50,75,100})milestones+=(percent>=step?"✦":"☆")+" "+Dates.fa(step)+"٪   ";ui.add(card,ui.text(milestones,12,Ui.GOLD));ui.add(card,ui.text("اعتبار: "+Dates.format(goal.optString("start"))+" تا "+Dates.format(goal.optString("end")),11,Ui.MUTED));ui.buttons(card,"ویرایش",()->forms.goal(goal),"حذف",()->remove("goals",goal));}}
    void cards(LinearLayout box){title(box,"کارنامهٔ پیشرفت","کارنامه از داده‌های همین دفتر، برای بازهٔ شمسی انتخاب‌شده ساخته می‌شود.");ui.buttons(box,"هفتگی",()->{a.cardPeriod="weekly";a.refresh();},"ماهانه",()->{a.cardPeriod="monthly";a.refresh();});range(box,a.cardPeriod);ReportData report=new ReportData(db,a.referenceDate,a.cardPeriod);LinearLayout card=ui.card(box);for(int i=0;i<report.lines.size();i++){ui.add(card,ui.text(report.lines.get(i),i==0?21:14,i==0?Ui.PURPLE:Ui.INK));ui.space(card,i<3?8:12);}ui.buttons(box,"ذخیرهٔ PDF",()->a.exporter.pdf(report),"چاپ / ذخیره در چاپگر",()->a.exporter.print(report));ui.add(box,ui.button("اشتراک متن کارنامه",false,()->a.exporter.shareText(report)));}
    void subjects(LinearLayout box){title(box,"درس‌های من","رنگ و نام درس‌ها را برای مسیر خودت انتخاب کن.");ui.add(box,ui.button("+ درس تازه",true,()->forms.subject(null)));if(db.all("subjects").isEmpty())ui.empty(box,"هنوز درسی نداری","برای گزارش زمان و ثبت آزمون، یک درس اضافه کن.");for(JSONObject subject:db.all("subjects")){LinearLayout card=ui.card(box),name=ui.row();name.addView(ui.text("●  ",19,Color.parseColor(subject.optString("color"))));name.addView(ui.text(subject.optString("name")+(subject.optBoolean("archived")?" • بایگانی":""),19,Ui.INK));ui.add(card,name);ui.buttons(card,"ویرایش",()->forms.subject(subject),subject.optBoolean("archived")?"بازگردانی":"بایگانی",()->{try{subject.put("archived",!subject.optBoolean("archived"));db.save("subjects",subject);a.refresh();}catch(JSONException error){throw new IllegalStateException(error);}});}}
    void more(LinearLayout box){title(box,"گوشهٔ دفتر تو","هرچه برای مرور مسیر و نگهداری اطلاعات لازم داری.");menu(box,"✦ هدف‌ها و ستاره‌ها","پیشرفت و گام‌های ۲۵ تا ۱۰۰ درصد","goals");menu(box,"▤ کارنامهٔ هفتگی و ماهانه","خروجی PDF، چاپ و اشتراک متن","cards");menu(box,"▦ درس‌های من","افزودن، ویرایش و بایگانی درس","subjects");menu(box,"⚙ تنظیمات و پشتیبان","پروفایل، ذخیره و بازیابی امن JSON","settings");}
    void menu(LinearLayout box,String title,String subtitle,String target){LinearLayout card=ui.card(box);ui.add(card,ui.label(title));ui.add(card,ui.text(subtitle,13,Ui.MUTED));ui.space(card,9);ui.add(card,ui.button("باز کردن  ←",false,()->a.navigate(target)));}
    void settings(LinearLayout box){title(box,"تنظیمات دفتر","دفتر مستقل و آفلاین؛ کنترل اطلاعات دست خود توست.");JSONObject profile=db.profile();LinearLayout card=ui.card(box);ui.add(card,ui.text(profile.optString("name"),22,Ui.PURPLE));ui.add(card,ui.text("پایهٔ "+Dates.fa(profile.optInt("grade"))+" • "+profile.optString("field"),14,Ui.MUTED));ui.stat(card,"هدف روزانه",Dates.fa(profile.optInt("dailyGoal"))+" دقیقه");ui.stat(card,"مقیاس نمره",Dates.fa(profile.optDouble("scale")));ui.add(card,ui.button("ویرایش پروفایل",false,forms::profile));
        LinearLayout backup=ui.card(box);ui.add(backup,ui.label("پشتیبان دفتر"));ui.add(backup,ui.text("فایل JSON شامل اطلاعات شخصی توست؛ آن را در محل مطمئن نگه دار. حذف برنامه یا پاک کردن داده‌های آن، دفتر محلی را پاک می‌کند. فایل پشتیبان در محلی که انتخاب می‌کنی باقی می‌ماند.",14,Ui.MUTED));ui.space(backup,10);ui.add(backup,ui.button("ذخیرهٔ فایل پشتیبان JSON",true,a.exporter::backup));ui.space(backup,10);ui.add(backup,ui.button("انتخاب پشتیبان برای بازیابی",false,a.exporter::importBackup));ui.space(backup,7);ui.add(backup,ui.text("فایل ابتدا بررسی می‌شود و تنها پس از تأیید تو، همهٔ رکوردهای دفتر به‌صورت یک تراکنش جایگزین می‌شوند. فایل نامعتبر هیچ داده‌ای را تغییر نمی‌دهد.",12,Ui.MUTED));
        LinearLayout privacy=ui.card(box);ui.add(privacy,ui.label("دربارهٔ نسخهٔ اندروید"));ui.add(privacy,ui.text("دفتر ستاره • نسخهٔ ۱٫۰٫۰\nبرنامهٔ بومی اندروید با ذخیره‌سازی SQLite روی همین گوشی. به رایانه، localhost، سرور یا اینترنت نیاز ندارد. ثبت‌نام، ورود پیامکی و همگام‌سازی ابری در این نسخه وجود ندارد. هیچ مجوز شبکه، مخاطب یا فضای ذخیره‌سازی گسترده درخواست نمی‌شود. برای انتخاب خروجی و پشتیبان، انتخابگر فایل خود اندروید باز می‌شود.\nفونت وزیرمتن با مجوز SIL Open Font License 1.1 استفاده شده است.",13,Ui.MUTED));
    }
    final class StudyChart extends View {
        final String start;final Paint paint=new Paint(Paint.ANTI_ALIAS_FLAG);final int[] minutes=new int[7];final String[] labels={"ش","ی","د","س","چ","پ","ج"};
        StudyChart(MainActivity context,String first){super(context);start=first;StringBuilder description=new StringBuilder("مطالعهٔ هفته: ");for(int i=0;i<7;i++){String day=LocalDate.parse(start).plusDays(i).toString();minutes[i]=db.totalMinutes(day,day);description.append(Dates.format(day)).append(" ").append(minutes[i]).append(" دقیقه؛ ");}setContentDescription(description.toString());setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_YES);}
        @Override protected void onDraw(Canvas canvas){super.onDraw(canvas);float width=getWidth(),height=getHeight(),gap=width/7;int max=30;for(int value:minutes)max=Math.max(max,value);paint.setTypeface(ui.font);paint.setTextAlign(Paint.Align.CENTER);for(int i=0;i<7;i++){float x=width-gap*(i+.5f),bar=(height-ui.dp(50))*minutes[i]/max;paint.setColor(0xffeeeaff);canvas.drawRoundRect(x-ui.dp(12),ui.dp(20),x+ui.dp(12),height-ui.dp(30),ui.dp(7),ui.dp(7),paint);paint.setColor(Ui.PURPLE);if(bar>0)canvas.drawRoundRect(x-ui.dp(12),height-ui.dp(30)-bar,x+ui.dp(12),height-ui.dp(30),ui.dp(7),ui.dp(7),paint);paint.setColor(Ui.MUTED);paint.setTextSize(ui.dp(11));canvas.drawText(labels[i],x,height-ui.dp(8),paint);canvas.drawText(Dates.fa(minutes[i]),x,Math.max(ui.dp(14),height-ui.dp(38)-bar),paint);}}
    }
    static final class GradientDrawableCompat {static void brand(Ui ui,View view){android.graphics.drawable.GradientDrawable drawable=new android.graphics.drawable.GradientDrawable(android.graphics.drawable.GradientDrawable.Orientation.TR_BL,new int[]{0xff6d5bf6,0xff4e3ad8});drawable.setCornerRadius(ui.dp(24));view.setBackground(drawable);}}
}
